def Popen(sCmd):
    import mxsubprocess
    oP = mxsubprocess.Popen(sCmd, stdout = mxsubprocess.PIPE, shell = True)
    (sOutput, sErr) = oP.communicate()
    if sErr:
        raise Exception(sErr)
    
    return sOutput


